const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const victoria = ee.Geometry.Point([-97.0039, 28.8014]); // Victoria, Texas
  const corpusChristi = ee.Geometry.Point([-97.3988, 27.8000]); // Corpus Christi, Texas
  const startDate = '2018-06-15';
  const endDate = '2018-06-23'; // Exclusive end date for 7 days (June 15 to June 22)

  const scale = 5566; // CHIRPS original resolution is 0.05 degrees, approx 5.5 km. Use this as scale.

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const chirpsSize = await chirps.size().getInfo();
  if (chirpsSize === 0) {
    console.log(`No CHIRPS data found for the period ${startDate} to ${endDate}.`);
    console.log("C1");
    return;
  }
  console.log(`CHIRPS images found: ${chirpsSize}`);

  // Calculate total rainfall for the period
  const totalRainfall = chirps.sum();

  if (!totalRainfall) {
    console.log("Calculation of total rainfall resulted in an empty image or null.");
    console.log("C3");
    return;
  }

  // Function to get rainfall for a given geometry
  const getRainfall = async (geometry, name) => {
    const reducerResult = await totalRainfall.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    // 3. Processing & Check for C2, C3
    if (reducerResult === null || isNaN(reducerResult)) {
      // Check if there are any valid pixels. For a point, if reducerResult is null, it means no valid pixel.
      // This is less likely with CHIRPS point, but good to check.
      const pixelCount = await totalRainfall.mask().reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geometry,
          scale: scale,
          maxPixels: 1e9
      }).get('precipitation').getInfo();

      if (pixelCount === 0) {
        console.log(`No valid pixels for ${name} after processing.`);
        console.log("C2");
      } else {
        console.log(`Calculation failed for ${name}: ${reducerResult}`);
        console.log("C3");
      }
      return null;
    }
    return reducerResult;
  };

  const victoriaRainfall_mm = await getRainfall(victoria, 'Victoria');
  const corpusChristiRainfall_mm = await getRainfall(corpusChristi, 'Corpus Christi');

  if (victoriaRainfall_mm === null || corpusChristiRainfall_mm === null) {
    // An error already occurred and was printed by getRainfall.
    return;
  }

  // 4. Calculation - Convert mm to inches
  const mmToInches = (mm) => mm / 25.4;

  const victoriaRainfall_in = mmToInches(victoriaRainfall_mm);
  const corpusChristiRainfall_in = mmToInches(corpusChristiRainfall_mm);

  console.log(`Victoria rainfall (inches): ${victoriaRainfall_in.toFixed(2)}`);
  console.log(`Corpus Christi rainfall (inches): ${corpusChristiRainfall_in.toFixed(2)}`);

  const threshold = 20; // inches

  // 5. Validation & Final Answer
  if (victoriaRainfall_in < threshold && corpusChristiRainfall_in < threshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
